@startuml

class Airplane {
  + Model : string
  + Price : double
  + DeliveryDate : date
}

class Acquisition {
  + Price : double
  + DeliveryDate : date
}

class Contract {
  + DeliveryConditions : string
  + LegalAspects : string
}

class Employee {
  + Name : string
}

class AirlineCompany {
  + Name : string
}

class Option {
  + Description : string
}

class Customization {
  + Description : string
}

Employee "1" -- "*" Contract : manages
Contract "1" *-- "1..*" Acquisition : consists of
AirlineCompany "1" -- "*" Contract : signs
AirlineCompany "0..1" -- "0..*" AirlineCompany : mother-daughter relationship
Acquisition "1" -- "1" Airplane : specifies
Acquisition "1" -- "*" Option : includes
Acquisition "1" -- "*" Customization : includes

@enduml

